using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeTypeFilterTests{[Fact]public void Constructs_and_normalizes(){var caller=new List<AstronomyKnowledgeTypeId>{AstronomyKnowledgeTypeId.Create("z"),AstronomyKnowledgeTypeId.Create("a"),AstronomyKnowledgeTypeId.Create("A")};var f=new AstronomyKnowledgeTypeFilter(caller);caller.Add(AstronomyKnowledgeTypeId.Create("b"));Assert.Equal(new[]{"a","z"},f.Values.Select(x=>x.Value));Assert.Throws<NotSupportedException>(()=>((IList<AstronomyKnowledgeTypeId>)f.Values).Add(AstronomyKnowledgeTypeId.Create("c")));}[Fact]public void Supports_all_mode(){var f=new AstronomyKnowledgeTypeFilter([AstronomyKnowledgeTypeId.Create("a")],AstronomyKnowledgeQueryMatchMode.All);Assert.Equal(AstronomyKnowledgeQueryMatchMode.All,f.MatchMode);}[Fact]public void Rejects_invalid_inputs(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeTypeFilter([]));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeTypeFilter([default]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeTypeFilter([AstronomyKnowledgeTypeId.Create("a")],(AstronomyKnowledgeQueryMatchMode)99));}}
